import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ref, onValue, update, remove } from 'firebase/database';
import { db } from '../firebase';
import axios from 'axios';

function SeriesDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [selectedUser, setSelectedUser] = useState('beyza');
  const [series, setSeries] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [continuousEpisodeNumbers, setContinuousEpisodeNumbers] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteLoading, setDeleteLoading] = useState(false);
  const [episodeDetailsMap, setEpisodeDetailsMap] = useState({});
  const [loadingEpisodes, setLoadingEpisodes] = useState({});

  const TMDB_API_KEY = 'YOUR_TMDB_API_KEY'; // TMDB API anahtarınızı buraya ekleyin
  const TMDB_BASE_URL = 'https://api.themoviedb.org/3';

  useEffect(() => {
    const seriesRef = ref(db, `series/${id}`);
    const unsubscribe = onValue(seriesRef, async (snapshot) => {
      if (snapshot.exists()) {
        const data = snapshot.val();
        console.log('Gelen veri:', data);
        console.log('seasonsData:', data.seasonsData);
        console.log('totalSeasons:', data.totalSeasons);
        setSeries({ id, ...data });
        setContinuousEpisodeNumbers(data.continuousEpisodeNumbers || false);
        
        // Eğer TMDB ID varsa, tüm sezonların bölüm detaylarını al
        if (data.tmdbId) {
          for (let season = 1; season <= data.totalSeasons; season++) {
            const episodeCount = data.seasonsData?.[season]?.episodes || 0;
            console.log(`Sezon ${season} bölüm sayısı:`, episodeCount);
            for (let episode = 1; episode <= episodeCount; episode++) {
              fetchEpisodeDetails(season, episode);
            }
          }
        }
      } else {
        setError('Dizi bulunamadı');
      }
      setLoading(false);
    }, (error) => {
      console.error('Dizi yüklenirken hata oluştu:', error);
      setError('Dizi yüklenirken bir hata oluştu');
      setLoading(false);
    });

    return () => unsubscribe();
  }, [id]);

  const fetchEpisodeDetails = async (seasonNumber, episodeNumber) => {
    if (!series?.tmdbId) return null;
    
    const cacheKey = `${seasonNumber}-${episodeNumber}`;
    if (episodeDetailsMap[cacheKey]) return episodeDetailsMap[cacheKey];
    
    setLoadingEpisodes(prev => ({ ...prev, [cacheKey]: true }));
    
    try {
      const response = await axios.get(`${TMDB_BASE_URL}/tv/${series.tmdbId}/season/${seasonNumber}/episode/${episodeNumber}`, {
        params: {
          api_key: TMDB_API_KEY,
          language: 'tr-TR'
        }
      });
      
      const details = {
        name: response.data.name,
        overview: response.data.overview,
        air_date: response.data.air_date,
        still_path: response.data.still_path ? `https://image.tmdb.org/t/p/w500${response.data.still_path}` : null
      };
      
      setEpisodeDetailsMap(prev => ({ ...prev, [cacheKey]: details }));
      return details;
    } catch (error) {
      console.error('Bölüm detayları alınamadı:', error);
      return null;
    } finally {
      setLoadingEpisodes(prev => ({ ...prev, [cacheKey]: false }));
    }
  };

  const toggleEpisodeWatched = async (seasonNumber, episodeNumber) => {
    if (!series) return;

    const newWatchedEpisodes = { ...series.watchedEpisodes };
    const episodeKey = `${seasonNumber}-${episodeNumber}`;
    
    if (series.watchingTogether) {
      // Birlikte izliyoruz modunda her iki kullanıcı için de aynı durumu uygula
      const newStatus = !newWatchedEpisodes.beyza[episodeKey];
      newWatchedEpisodes.beyza[episodeKey] = newStatus;
      newWatchedEpisodes.mucahit[episodeKey] = newStatus;
    } else {
      // Normal modda sadece seçili kullanıcı için durumu değiştir
      newWatchedEpisodes[selectedUser][episodeKey] = !newWatchedEpisodes[selectedUser][episodeKey];
    }

    try {
      await update(ref(db, `series/${id}`), {
        watchedEpisodes: newWatchedEpisodes
      });
    } catch (error) {
      console.error('Bölüm durumu güncellenirken hata oluştu:', error);
    }
  };

  const toggleSeasonWatched = async (seasonNumber) => {
    if (!series) return;

    const newWatchedEpisodes = { ...series.watchedEpisodes };
    const seasonEpisodes = series.seasonsData[seasonNumber]?.episodes || 0;
    
    if (series.watchingTogether) {
      // Birlikte izliyoruz modunda her iki kullanıcı için de aynı durumu uygula
      const isSeasonWatched = newWatchedEpisodes.beyza[`${seasonNumber}-1`];
      for (let episode = 1; episode <= seasonEpisodes; episode++) {
        const episodeKey = `${seasonNumber}-${episode}`;
        newWatchedEpisodes.beyza[episodeKey] = !isSeasonWatched;
        newWatchedEpisodes.mucahit[episodeKey] = !isSeasonWatched;
      }
    } else {
      // Normal modda sadece seçili kullanıcı için durumu değiştir
      const isSeasonWatched = newWatchedEpisodes[selectedUser][`${seasonNumber}-1`];
      for (let episode = 1; episode <= seasonEpisodes; episode++) {
        const episodeKey = `${seasonNumber}-${episode}`;
        newWatchedEpisodes[selectedUser][episodeKey] = !isSeasonWatched;
      }
    }

    try {
      await update(ref(db, `series/${id}`), {
        watchedEpisodes: newWatchedEpisodes
      });
    } catch (error) {
      console.error('Sezon durumu güncellenirken hata oluştu:', error);
    }
  };

  const toggleContinuousEpisodeNumbers = async () => {
    if (!series) return;
    
    const newValue = !continuousEpisodeNumbers;
    setContinuousEpisodeNumbers(newValue);
    
    try {
      await update(ref(db, `series/${id}`), {
        continuousEpisodeNumbers: newValue
      });
    } catch (error) {
      console.error('Bölüm numaralandırma tercihi güncellenirken hata oluştu:', error);
    }
  };

  const getEpisodeNumber = (seasonNumber, episodeNumber) => {
    if (!continuousEpisodeNumbers) return episodeNumber;
    
    let totalEpisodes = 0;
    for (let s = 1; s < seasonNumber; s++) {
      totalEpisodes += series?.seasonsData[s]?.episodes || 0;
    }
    return totalEpisodes + episodeNumber;
  };

  const handleDeleteClick = () => {
    setShowDeleteConfirm(true);
  };

  const deleteSeries = async () => {
    setDeleteLoading(true);
    try {
      await remove(ref(db, `series/${id}`));
      navigate('/series');
    } catch (error) {
      console.error('Dizi silinirken hata oluştu:', error);
      setError('Dizi silinirken bir hata oluştu');
    } finally {
      setDeleteLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-purple-50 to-pink-50">
        <div className="animate-spin rounded-full h-12 w-12 border-4 border-purple-500 border-t-transparent"></div>
      </div>
    );
  }

  if (error || !series) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-purple-50 to-pink-50">
        <div className="text-center">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">Hata</h2>
          <p className="text-gray-600 mb-4">{error || 'Dizi bulunamadı'}</p>
          <button
            onClick={() => navigate('/series')}
            className="px-4 py-2 bg-gradient-to-r from-purple-600 to-pink-600 text-white rounded-lg hover:from-purple-700 hover:to-pink-700 transition duration-200"
          >
            Dizilere Dön
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen relative">
      {/* Yarı saydam arka plan */}
      <div 
        className="fixed inset-0 opacity-20"
        style={{
          backgroundImage: series.coverImage ? `url(${series.coverImage})` : 'none',
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          backgroundRepeat: 'no-repeat',
          width: '100vw',
          height: '100vh',
          zIndex: -1
        }}
      />
      
      {/* Gradient overlay */}
      <div 
        className="fixed inset-0 bg-gradient-to-br from-purple-50/90 to-pink-50/90"
        style={{ 
          zIndex: -1,
          width: '100vw',
          height: '100vh'
        }}
      />

      {/* Silme Onay Modalı */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-md w-full mx-4 shadow-xl">
            <h3 className="text-xl font-bold text-gray-800 mb-4">Diziyi Sil</h3>
            <p className="text-gray-600 mb-6">
              <span className="font-semibold">{series.title}</span> dizisini silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.
            </p>
            <div className="flex justify-end space-x-3">
              <button
                onClick={() => setShowDeleteConfirm(false)}
                className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 transition duration-200"
                disabled={deleteLoading}
              >
                İptal
              </button>
              <button
                onClick={deleteSeries}
                className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition duration-200 flex items-center"
                disabled={deleteLoading}
              >
                {deleteLoading ? (
                  <>
                    <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Siliniyor...
                  </>
                ) : (
                  'Sil'
                )}
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="py-8 px-4">
        <div className="max-w-6xl mx-auto">
          <div className="flex justify-between items-center mb-8">
            <div>
              <h1 className="text-3xl font-bold text-gray-800 mb-2">{series.title}</h1>
              <div className="flex items-center space-x-4">
                <span className="text-sm text-gray-600">Sezon {series.currentSeason}</span>
                <span className="text-sm text-gray-600">Bölüm {series.currentEpisode}</span>
                {series.watchingTogether && (
                  <span className="text-xs bg-purple-100 text-purple-700 px-2 py-1 rounded-full">
                    Birlikte İzliyoruz
                  </span>
                )}
              </div>
            </div>
            <div className="flex space-x-3">
              <button
                onClick={() => navigate(`/series/${id}/edit`)}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition duration-200 flex items-center"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" viewBox="0 0 20 20" fill="currentColor">
                  <path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" />
                </svg>
                Düzenle
              </button>
              <button
                onClick={handleDeleteClick}
                className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition duration-200 flex items-center"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" />
                </svg>
                Sil
              </button>
            </div>
          </div>

          {/* Bölüm Numaralandırma Tercihi */}
          <div className="bg-white/90 backdrop-blur-sm rounded-xl shadow-lg p-4 mb-6">
            <div className="flex items-center justify-between">
              <span className="text-gray-700">Bölüm Numaralandırma</span>
              <button
                onClick={toggleContinuousEpisodeNumbers}
                className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none ${
                  continuousEpisodeNumbers ? 'bg-purple-600' : 'bg-gray-300'
                }`}
              >
                <span
                  className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                    continuousEpisodeNumbers ? 'translate-x-6' : 'translate-x-1'
                  }`}
                />
              </button>
            </div>
            <p className="text-sm text-gray-500 mt-1">
              {continuousEpisodeNumbers 
                ? 'Bölümler sürekli numaralandırılıyor (1, 2, 3, ...)' 
                : 'Bölümler sezon bazında numaralandırılıyor (S1E1, S1E2, ...)'}
            </p>
          </div>

          {/* Debug bilgileri */}
          <div className="bg-white/90 backdrop-blur-sm rounded-xl shadow-lg p-4 mb-6">
            <h3 className="font-bold text-gray-800 mb-2">Debug Bilgileri</h3>
            <pre className="text-xs text-gray-600 overflow-auto">
              {JSON.stringify({
                totalSeasons: series?.totalSeasons,
                seasonsData: series?.seasonsData,
                watchedEpisodes: series?.watchedEpisodes,
                selectedUser,
                continuousEpisodeNumbers
              }, null, 2)}
            </pre>
          </div>

          {/* Sezonlar */}
          <div className="space-y-6">
            {series?.totalSeasons && Array.from({ length: series.totalSeasons }, (_, i) => i + 1).map((seasonNumber) => {
              console.log(`Sezon ${seasonNumber} render ediliyor`);
              console.log(`Sezon ${seasonNumber} bölüm sayısı:`, series.seasonsData?.[seasonNumber]?.episodes);
              
              return (
                <div key={seasonNumber} className="bg-white/90 backdrop-blur-sm rounded-xl shadow-lg overflow-hidden">
                  <div className="bg-gradient-to-r from-purple-600 to-pink-600 p-4 flex justify-between items-center">
                    <h2 className="text-xl font-bold text-white">Sezon {seasonNumber}</h2>
                    <button
                      onClick={() => toggleSeasonWatched(seasonNumber)}
                      className="px-3 py-1 bg-white/20 text-white rounded-lg hover:bg-white/30 transition duration-200 text-sm"
                    >
                      {series.watchedEpisodes?.[selectedUser]?.[`${seasonNumber}-1`] ? 'Sezonu İzlenmedi Olarak İşaretle' : 'Sezonu İzlendi Olarak İşaretle'}
                    </button>
                  </div>
                  <div className="p-4">
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                      {Array.from({ length: series.seasonsData?.[seasonNumber]?.episodes || 0 }, (_, i) => i + 1).map((episodeNumber) => {
                        const episodeKey = `${seasonNumber}-${episodeNumber}`;
                        console.log(`Bölüm ${episodeKey} render ediliyor`);
                        
                        return (
                          <div 
                            key={episodeNumber}
                            className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition duration-200"
                          >
                            <div className="p-4">
                              <div className="flex justify-between items-center mb-2">
                                <h3 className="font-semibold text-gray-800">
                                  Bölüm {getEpisodeNumber(seasonNumber, episodeNumber)}
                                </h3>
                                <button
                                  onClick={() => toggleEpisodeWatched(seasonNumber, episodeNumber)}
                                  className={`p-2 rounded-full transition duration-200 ${
                                    series.watchedEpisodes?.[selectedUser]?.[episodeKey]
                                      ? 'bg-green-100 text-green-700 hover:bg-green-200' 
                                      : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                  }`}
                                >
                                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                    <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                                  </svg>
                                </button>
                              </div>
                              
                              {loadingEpisodes[episodeKey] ? (
                                <div className="animate-pulse">
                                  <div className="h-4 bg-gray-200 rounded w-3/4 mb-2"></div>
                                  <div className="h-4 bg-gray-200 rounded w-1/2"></div>
                                </div>
                              ) : episodeDetailsMap[episodeKey] ? (
                                <div>
                                  <h4 className="font-medium text-gray-700 mb-1">{episodeDetailsMap[episodeKey].name}</h4>
                                  <p className="text-sm text-gray-600 mb-2">{episodeDetailsMap[episodeKey].overview}</p>
                                  <div className="text-xs text-gray-500">
                                    Yayın Tarihi: {new Date(episodeDetailsMap[episodeKey].air_date).toLocaleDateString('tr-TR')}
                                  </div>
                                </div>
                              ) : (
                                <div className="text-sm text-gray-500">
                                  Bölüm detayları yüklenemedi
                                </div>
                              )}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

export default SeriesDetail;
